labelB.moveTo([2.6, 2.8, 0]);
scene.add(title, labelA, labelB);

const axes = new Axes({ xRange: [0, 600, 150], yRange: [0, 90, 20], xLength: 9, yLength: 4.4, tips: false });
const costA = m => 20 + 0.10 * m;
const costB = m => 35 + 0.05 * m;
const curveA = axes.plot(costA, { color: BLUE });
const curveB = axes.plot(costB, { color: GREEN });
await scene.play(new AnimationGroup([new Create(axes), new Create(curveA), new Create(curveB)]));

for (const m of [0, 150, 300, 450, 600]) {
  const tickLabel = new Text({ text: String(m), fontSize: 17, color: GRAY });
  const p = axes.c2p(m, 0);
  tickLabel.moveTo([p[0], p[1] - 0.28, 0]);
  scene.add(tickLabel);
}
for (const dollars of [20, 40, 60, 80]) {
  const tickLabel = new Text({ text: '$' + dollars, fontSize: 17, color: GRAY });
  const p = axes.c2p(0, dollars);
  tickLabel.moveTo([p[0] - 0.45, p[1], 0]);
  scene.add(tickLabel);
}
const minutesLabel = new Text({ text: 'minutes', fontSize: 18, color: GRAY });
minutesLabel.moveTo([5.2, -2.2, 0]);
scene.add(minutesLabel);

let minutes = 160;
const guide = new DashedLine({ start: axes.c2p(minutes, 0), end: axes.c2p(minutes, 60), color: YELLOW });
const gap = new Line({ start: axes.c2p(minutes, costA(minutes)), end: axes.c2p(minutes, costB(minutes)), color: YELLOW });
gap.setStrokeWidth(5);
const dotA = new Dot({ point: axes.c2p(minutes, costA(minutes)), radius: 0.09, color: BLUE });
const dotB = new Dot({ point: axes.c2p(minutes, costB(minutes)), radius: 0.09, color: GREEN });
const handle = new Dot({ point: axes.c2p(minutes, 0), radius: 0.14, color: YELLOW });
const intersection = new Circle({ radius: 0.16, color: WHITE });
intersection.moveTo(axes.c2p(300, 50));
const crossingLabel = new Text({ text: '300 min · $50', fontSize: 22, color: WHITE });
const crossingPoint = axes.c2p(300, 50);
crossingLabel.moveTo([crossingPoint[0] - 0.3, crossingPoint[1] + 0.55, 0]);
const readout = new Text({ text: '', fontSize: 23, color: WHITE });
readout.moveTo([0, -2.95, 0]);
const status = new Text({ text: '', fontSize: 21, color: YELLOW });
status.moveTo([2.5, 1.95, 0]);
const hint = new Text({ text: 'Drag the yellow minute handle — compare the two costs', fontSize: 20, color: GRAY });
hint.moveTo([0, -3.45, 0]);
scene.add(guide, gap, intersection, crossingLabel, dotA, dotB, handle, readout, status, hint);

function update() {
  const a = costA(minutes);
  const b = costB(minutes);
  handle.moveTo(axes.c2p(minutes, 0));
  dotA.moveTo(axes.c2p(minutes, a));
  dotB.moveTo(axes.c2p(minutes, b));
  guide.setStart(axes.c2p(minutes, 0));
  guide.setEnd(axes.c2p(minutes, Math.max(a, b)));
  gap.setStart(axes.c2p(minutes, a));
  gap.setEnd(axes.c2p(minutes, b));
  gap.setOpacity(minutes === 300 ? 0 : 1);
  readout.setText(minutes + ' min     A: $' + a.toFixed(2) + '     B: $' + b.toFixed(2));
  if (minutes === 300) {
    status.setText('Equal: both cost $50!');
    status.setColor(YELLOW);
  } else {
    status.setText((a < b ? 'A' : 'B') + ' saves $' + Math.abs(a - b).toFixed(2));
    status.setColor(a < b ? BLUE : GREEN);
  }
}
update();
makeDraggable(handle, scene, { onDrag: (mob, pos) => {
  minutes = Math.max(0, Math.min(600, Math.round(axes.pointToCoords(pos)[0])));
  update();
} });
makeClickable(crossingLabel, scene, { onClick: () => { minutes = 300; update(); } });
await scene.wait(999999);"}

